package com.wissenup.domain.timetable.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="teacher_substitutions") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class TeacherSubstitution { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="substitution_id") private Long substitutionId; @Column(name="organization_id") private Long organizationId; @Column(name="timetable_detail_id") private Long timetableDetailId; @Column(name="substitution_date") private LocalDate substitutionDate; @Column(name="substitute_staff_id") private Long substituteStaffId; private String reason; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(createdAt==null)createdAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
